import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Instant;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

class OrderServicePlacedOnTest {

    private final OrderService orders = new OrderService(new OrderRepository());

    @Test
    void countsByWarsawDayNotUtcDay() {
        // 23:30 UTC on Jan 10 is 00:30 on Jan 11 in Warsaw (UTC+1).
        orders.place("c-1", Money.pln(100), Instant.parse("2026-01-10T23:30:00Z"));

        assertEquals(0, orders.placedOn(LocalDate.of(2026, 1, 10)));
        assertEquals(1, orders.placedOn(LocalDate.of(2026, 1, 11)));
    }

    @Test
    void summerMidnightBoundaryIsWarsawMidnight() {
        // Warsaw is UTC+2 in summer: 22:00Z is midnight, so 21:59:59Z is still June 30.
        orders.place("c-1", Money.pln(100), Instant.parse("2026-06-30T21:59:59Z"));
        orders.place("c-2", Money.pln(100), Instant.parse("2026-06-30T22:00:00Z"));

        assertEquals(1, orders.placedOn(LocalDate.of(2026, 6, 30)));
        assertEquals(1, orders.placedOn(LocalDate.of(2026, 7, 1)));
    }

    @Test
    void noOrdersMeansZero() {
        assertEquals(0, orders.placedOn(LocalDate.of(2026, 1, 1)));
    }
}
